def _check_configs(self):
        """
        Reloads the configuration files.
        """
        if self.configs:
            for config in self.configs:
                if config.config_type == "file":
                    self.configs.remove(config)
                    self.configs.append(
                        ConfigFile(config.config_file_path, config.config_file_name)
                    )
                elif config.config_type == "db":
                    self.configs.remove(config)
                    self.configs.append(
                        ConfigDB(config.config_file_path, config.config_file_name)
                    )

